onClick:
{{
  Insert_Commande_Client.run()
    .then((res) => {
      if (!res || !res[0]) return Promise.reject("Pas d'ID");

      // Le correctif magique pour contrer les caprices de PostgreSQL
      const newId = res[0].ID_Commande_Client || res[0].id_commande_client;
      if (!newId) return Promise.reject("Pas d'ID");

      // 1ère tentative : On récupère les données IMMÉDIATEMENT
      return Get_Commandes_Clients.run().then((data) => ({ id: newId, donnees: data }));
    })
    .then((resultat) => {
      let index = resultat.donnees.findIndex(c => String(c.ID_Commande_Client) === String(resultat.id));

      if (index > -1) {
        // Trouvée du 1er coup ! On passe à la suite sans attendre
        return { id: resultat.id, finalIndex: index };
      } else {
        // Pas trouvée (Supabase est ralenti). On fait une pause de 1 seconde et on retente !
        return new Promise(resolve => setTimeout(resolve, 1500))
          .then(() => Get_Commandes_Clients.run())
          .then((nouvellesDonnees) => {
            const indexSecours = nouvellesDonnees.findIndex(c => String(c.ID_Commande_Client) === String(resultat.id));
            return { id: resultat.id, finalIndex: indexSecours };
          });
      }
    })
    .then((final) => {
      // On ferme et on nettoie la modale de création
      closeModal('modal_add_commande');
      resetWidget('sel_client', true);
      resetWidget('inp_new_notes', true);

      if (final.finalIndex > -1) {
        // Si la ligne est trouvée, on l'ouvre
        storeValue('targetIndex', final.finalIndex);
        setTimeout(() => { showModal('Vue_detail_commande_client'); }, 400);
      } else {
        // Si elle n'est toujours pas sur la page 1 du tableau
        showAlert("Commande créée ! (Elle se trouve plus bas dans la liste)", "success");
      }
    })
    .catch((err) => {
      if (err !== "Pas d'ID") showAlert('Erreur lors de la création', 'error');
    });
}}
